class Solution {
public:
 int minimumVisitedCells(vector<vector<int>>& grid){
  int m=grid.size(),n=grid[0].size();
  using P=pair<int,int>;
  vector<priority_queue<P,vector<P>,greater<P>>> cols(n);
  for(int i=0;i<m;++i){
   priority_queue<P,vector<P>,greater<P>> row;
   for(int j=0;j<n;++j){
    while(!row.empty()&&row.top().second<j)row.pop();
    while(!cols[j].empty()&&cols[j].top().second<i)cols[j].pop();
    int d=INT_MAX;
    if(i==0&&j==0)d=1;
    if(!row.empty())d=min(d,row.top().first+1);
    if(!cols[j].empty())d=min(d,cols[j].top().first+1);
    if(i==m-1&&j==n-1)return d==INT_MAX?-1:d;
    if(d!=INT_MAX&&grid[i][j]>0){
     row.push({d,j+grid[i][j]});
     cols[j].push({d,i+grid[i][j]});
    }
   }
  }return -1;
 }
};
